import type { Minstd } from './minstd.ts';

export interface Dice {
  count: number;
  sides: number;
}
export function parseDice(text: string): Dice {
  const [count, sides] = text.split('d').map(Number);
  return { count, sides };
}
export interface Attack {
  hit: boolean;
  critical: boolean;
  damage: number;
}
export function attack(
  rng: Minstd,
  modifier: number,
  defense: number,
  dice: Dice,
  bonus: number,
): Attack {
  const roll = 1 + rng.rnd(20);
  if (roll === 1 || (roll !== 20 && roll + modifier < defense)) {
    return { hit: false, critical: false, damage: 0 };
  }
  const critical = roll === 20;
  let damage = rng.roll(dice);
  if (critical) damage += rng.roll(dice);
  return { hit: true, critical, damage: Math.max(1, damage + bonus) };
}

import type { Item, Monster, Position } from './entities.ts';
import type { Minstd } from './minstd.ts';

export interface GenerationConfig {
  width: number;
  height: number;
  minimum: number;
  splits: number;
  roomMin: number;
  roomMax: number;
}
interface Region {
  x: number;
  y: number;
  w: number;
  h: number;
  rooms: number[];
  children?: [Region, Region];
}
export interface Room {
  x: number;
  y: number;
  w: number;
  h: number;
  cx: number;
  cy: number;
}
export interface RoomCell extends Position {
  room: number;
}
export class Level {
  terrain: string[];
  memory: string[];
  rooms: Room[] = [];
  monsters: Monster[] = [];
  items: Item[] = [];
  arrival: RoomCell;
  target: RoomCell;
  killed = 0;
  picked = 0;
  created = 0;
  placed = 0;
  constructor(
    readonly width: number,
    readonly height: number,
    config: GenerationConfig,
    rng: Minstd,
  ) {
    this.terrain = Array<string>(width * height).fill(' ');
    this.memory = Array<string>(width * height).fill(' ');
    const leaves: Region[] = [];
    const split = (x: number, y: number, w: number, h: number, depth: number): Region => {
      const node: Region = { x, y, w, h, rooms: [] };
      const cv = w >= 2 * config.minimum;
      const ch = h >= 2 * config.minimum;
      if (depth === config.splits || (!cv && !ch)) {
        node.rooms.push(leaves.length);
        leaves.push(node);
        return node;
      }
      let vertical: boolean;
      if (cv && ch) vertical = 4 * w >= 5 * h ? true : 4 * h >= 5 * w ? false : rng.rnd(2) === 0;
      else vertical = cv;
      const c = config.minimum + rng.rnd((vertical ? w : h) - 2 * config.minimum + 1);
      const a = split(x, y, vertical ? c : w, vertical ? h : c, depth + 1);
      const b = split(
        vertical ? x + c : x,
        vertical ? y : y + c,
        vertical ? w - c : w,
        vertical ? h : h - c,
        depth + 1,
      );
      node.children = [a, b];
      node.rooms = [...a.rooms, ...b.rooms];
      return node;
    };
    const root = split(0, 0, width, height, 0);
    for (const leaf of leaves) {
      const w = config.roomMin + rng.rnd(Math.min(config.roomMax, leaf.w - 1) - config.roomMin + 1);
      const h = config.roomMin + rng.rnd(Math.min(config.roomMax, leaf.h - 1) - config.roomMin + 1);
      const x = leaf.x + rng.rnd(leaf.w - w);
      const y = leaf.y + rng.rnd(leaf.h - h);
      this.rooms.push({ x, y, w, h, cx: x + Math.floor(w / 2), cy: y + Math.floor(h / 2) });
      for (let yy = y; yy < y + h; yy++) {
        for (let xx = x; xx < x + w; xx++) {
          this.terrain[this.index(xx, yy)] =
            yy === y || yy === y + h - 1 ? '-' : xx === x || xx === x + w - 1 ? '|' : '.';
        }
      }
    }
    const carve = (x: number, y: number) => {
      const i = this.index(x, y);
      const cell = this.terrain[i];
      if (cell === ' ') this.terrain[i] = '#';
      else if (cell === '-' || cell === '|') this.terrain[i] = '+';
    };
    const segment = (x: number, y: number, endX: number, endY: number) => {
      const dx = Math.sign(endX - x);
      const dy = Math.sign(endY - y);
      carve(x, y);
      while (x !== endX || y !== endY) {
        x += dx;
        y += dy;
        carve(x, y);
      }
    };
    const connect = (node: Region): void => {
      if (!node.children) return;
      const [first, second] = node.children;
      connect(first);
      connect(second);
      let distance = width + height;
      let a = this.rooms[first.rooms[0]];
      let b = this.rooms[second.rooms[0]];
      for (const i of first.rooms) {
        for (const j of second.rooms) {
          const aa = this.rooms[i];
          const bb = this.rooms[j];
          const d = Math.abs(aa.cx - bb.cx) + Math.abs(aa.cy - bb.cy);
          if (d < distance) {
            distance = d;
            a = aa;
            b = bb;
          }
        }
      }
      if (rng.rnd(2) === 0) {
        segment(a.cx, a.cy, b.cx, a.cy);
        segment(b.cx, a.cy, b.cx, b.cy);
      } else {
        segment(a.cx, a.cy, a.cx, b.cy);
        segment(a.cx, b.cy, b.cx, b.cy);
      }
    };
    connect(root);
    this.arrival = this.drawCell(rng);
    this.terrain[this.index(this.arrival.x, this.arrival.y)] = '<';
    let targetRoom = rng.rnd(this.rooms.length - 1);
    if (targetRoom >= this.arrival.room) targetRoom++;
    this.target = this.drawInterior(targetRoom, rng);
  }
  index(x: number, y: number): number {
    return y * this.width + x;
  }
  at(x: number, y: number): string {
    return this.terrain[this.index(x, y)];
  }
  drawInterior(room: number, rng: Minstd): RoomCell {
    const r = this.rooms[room];
    const x = r.x + 1 + rng.rnd(r.w - 2);
    const y = r.y + 1 + rng.rnd(r.h - 2);
    return { room, x, y };
  }
  drawCell(rng: Minstd): RoomCell {
    return this.drawInterior(rng.rnd(this.rooms.length), rng);
  }
  monsterAt(x: number, y: number): Monster | undefined {
    return this.monsters.find((m) => m.x === x && m.y === y);
  }
  itemAt(x: number, y: number): Item | undefined {
    return this.items.find((item) => item.x === x && item.y === y);
  }
}

import { parseDice, type Dice } from './combat.ts';

interface TypeBase {
  name: string;
  minDepth: number;
  maxDepth: number;
  weight: number;
}
export interface MonsterType extends TypeBase {
  symbol: string;
  hp: Dice;
  toHit: number;
  defense: number;
  damage: Dice;
  speed: number;
  xp: number;
  traits: string;
}
export interface Position {
  x: number;
  y: number;
}
export interface Monster extends Position {
  id: number;
  type: MonsterType;
  hp: number;
  maxHp: number;
  asleep: boolean;
  energy: number;
  wasVisible: boolean;
}
type PotionEffect =
  { effect: 'heal'; dice: Dice } | { effect: 'poison'; turns: number } | { effect: 'level' };
export type ItemType = TypeBase &
  (
    | { kind: 'weapon'; damage: Dice; toHit: number }
    | { kind: 'armor'; armor: number }
    | ({ kind: 'potion' } & PotionEffect)
    | { kind: 'scroll'; effect: 'mapping' | 'teleport' | 'enchant_weapon' | 'enchant_armor' }
    | { kind: 'food'; satiation: number }
    | { kind: 'gold'; dice: Dice }
    | { kind: 'amulet' }
  );
export interface Item extends Position {
  type: ItemType;
  bonus: number;
  amount: number;
}
export function monsterType(line: string): MonsterType {
  const t = line.split(' ');
  return {
    name: t[0],
    symbol: t[1],
    minDepth: +t[2],
    maxDepth: +t[3],
    weight: +t[4],
    hp: parseDice(t[5]),
    toHit: +t[6],
    defense: +t[7],
    damage: parseDice(t[8]),
    speed: +t[9],
    xp: +t[10],
    traits: t[11],
  };
}
export function itemType(line: string): ItemType {
  const t = line.split(' ');
  const base = { name: t[1], minDepth: +t[2], maxDepth: +t[3], weight: +t[4] };
  switch (t[0]) {
    case 'weapon':
      return { ...base, kind: 'weapon', damage: parseDice(t[5]), toHit: +t[6] };
    case 'armor':
      return { ...base, kind: 'armor', armor: +t[5] };
    case 'food':
      return { ...base, kind: 'food', satiation: +t[5] };
    case 'gold':
      return { ...base, kind: 'gold', dice: parseDice(t[5]) };
    case 'potion':
      if (t[5] === 'heal') {
        return { ...base, kind: 'potion', effect: 'heal', dice: parseDice(t[6]) };
      }
      if (t[5] === 'poison') return { ...base, kind: 'potion', effect: 'poison', turns: +t[6] };
      return { ...base, kind: 'potion', effect: 'level' };
    case 'scroll': {
      const effect = t[5];
      if (
        effect === 'mapping' ||
        effect === 'teleport' ||
        effect === 'enchant_weapon' ||
        effect === 'enchant_armor'
      ) {
        return { ...base, kind: 'scroll', effect };
      }
    }
  }
  throw new Error('Unknown item type');
}
export function makeItem(type: ItemType, x = -1, y = -1): Item {
  return { type, x, y, bonus: 0, amount: 0 };
}
export function symbol(item: Item): string {
  return { weapon: ')', armor: '[', potion: '!', scroll: '?', food: '%', gold: '$', amulet: '"' }[
    item.type.kind
  ];
}
export function displayName(item: Item): string {
  const name = item.type.name.replaceAll('_', ' ');
  if (item.type.kind === 'weapon' || item.type.kind === 'armor') return `+${item.bonus} ${name}`;
  return item.type.kind === 'gold' ? `${item.amount} gold` : name;
}
export function referenceName(item: Item): string {
  return (item.type.kind === 'gold' ? '' : 'the ') + displayName(item);
}

import type { Level } from './dungeon_gen.ts';
import type { Position } from './entities.ts';

export const directions = [
  { name: 'N', x: 0, y: -1 },
  { name: 'NE', x: 1, y: -1 },
  { name: 'E', x: 1, y: 0 },
  { name: 'SE', x: 1, y: 1 },
  { name: 'S', x: 0, y: 1 },
  { name: 'SW', x: -1, y: 1 },
  { name: 'W', x: -1, y: 0 },
  { name: 'NW', x: -1, y: -1 },
];
export function passable(level: Level, x: number, y: number): boolean {
  return (
    x >= 0 && x < level.width && y >= 0 && y < level.height && '.#+<>'.includes(level.at(x, y))
  );
}
export function canMove(level: Level, x: number, y: number, dx: number, dy: number): boolean {
  return (
    passable(level, x + dx, y + dy) &&
    (!dx || !dy || (level.at(x, y) !== '+' && level.at(x + dx, y + dy) !== '+'))
  );
}
export function line(x: number, y: number, endX: number, endY: number): Position[] {
  const dx = Math.abs(endX - x);
  const dy = Math.abs(endY - y);
  const sx = endX > x ? 1 : -1;
  const sy = endY > y ? 1 : -1;
  let err = dx - dy;
  const cells: Position[] = [];
  while (x !== endX || y !== endY) {
    const e2 = 2 * err;
    if (e2 > -dy) {
      err -= dy;
      x += sx;
    }
    if (e2 < dx) {
      err += dx;
      y += sy;
    }
    cells.push({ x, y });
  }
  return cells;
}
export function fieldOfView(level: Level, px: number, py: number, radius: number): Set<number> {
  const visible = new Set<number>();
  for (let y = 0; y < level.height; y++) {
    for (let x = 0; x < level.width; x++) {
      if ((x - px) ** 2 + (y - py) ** 2 > radius ** 2) continue;
      const cells = line(px, py, x, y);
      if (cells.slice(0, -1).every((cell) => passable(level, cell.x, cell.y))) {
        visible.add(level.index(x, y));
      }
    }
  }
  return visible;
}
export function distances(level: Level, px: number, py: number): number[] {
  const dist = Array<number>(level.width * level.height).fill(-1);
  const queue: Position[] = [{ x: px, y: py }];
  dist[level.index(px, py)] = 0;
  for (let head = 0; head < queue.length; head++) {
    const { x, y } = queue[head];
    for (const d of directions) {
      if (!canMove(level, x, y, d.x, d.y)) continue;
      const nx = x + d.x;
      const ny = y + d.y;
      const i = level.index(nx, ny);
      if (dist[i] >= 0) continue;
      dist[i] = dist[level.index(x, y)] + 1;
      queue.push({ x: nx, y: ny });
    }
  }
  return dist;
}

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { attack, parseDice, type Attack } from './combat.ts';
import { Level, type RoomCell } from './dungeon_gen.ts';
import {
  displayName,
  itemType,
  makeItem,
  monsterType,
  referenceName,
  symbol,
  type Monster,
} from './entities.ts';
import { canMove, directions, distances, fieldOfView, passable } from './fov.ts';
import { Minstd } from './minstd.ts';

function lines(path: string): string[] {
  return readFileSync(path, 'ascii').trimEnd().split('\n');
}
const config = lines('input/config.txt').map((line) => line.split(' ').slice(1));
const numbers = (i: number) => config[i].map(Number);
const [generationSeed, gameSeed] = numbers(0);
const [width, height] = numbers(1);
const [minimum, splits] = numbers(2);
const [roomMin, roomMax] = numbers(3);
const [levelCount] = numbers(4);
const [monsterBase, monsterStep] = numbers(5);
const [itemBase, itemStep] = numbers(6);
const [sleepChance, wakeChance] = numbers(7);
const [radius] = numbers(8);
const [initialHp, regenInterval] = numbers(9);
const hitdie = parseDice(config[10][0]);
const [initialFood, maximumFood, hungryAt, weakAt] = numbers(11);
const [packLimit] = numbers(12);
const thresholds = numbers(14);
const checkpoints = new Set(numbers(15));
const generation = new Minstd(generationSeed);
const game = new Minstd(gameSeed);
const monsterTypes = lines('input/monsters.txt').map(monsterType);
const itemTypes = lines('input/items.txt').map(itemType);
const commands: string[][] = [];
for (const line of lines('input/commands.txt')) {
  const parts = line.split(' ');
  const repetitions =
    parts[0] === 'move' ? +(parts[2] ?? 1) : parts[0] === 'wait' ? +(parts[1] ?? 1) : 1;
  for (let i = 0; i < repetitions; i++) commands.push(parts);
}
const levels: Level[] = [];
for (let d = 1; d <= levelCount; d++) {
  const level = new Level(
    width,
    height,
    { width, height, minimum, splits, roomMin, roomMax },
    generation,
  );
  const target = level.target;
  if (d < levelCount) level.terrain[level.index(target.x, target.y)] = '>';
  else {
    level.items.push(
      makeItem(
        { kind: 'amulet', name: 'amulet', minDepth: d, maxDepth: d, weight: 1 },
        target.x,
        target.y,
      ),
    );
  }
  const candidates = monsterTypes.filter((type) => type.minDepth <= d && d <= type.maxDepth);
  level.created = monsterBase + monsterStep * (d - 1);
  for (let id = 1; id <= level.created; id++) {
    const type = generation.select(candidates);
    let cell: RoomCell;
    do {
      cell = level.drawCell(generation);
    } while (
      cell.room === level.arrival.room ||
      level.at(cell.x, cell.y) !== '.' ||
      level.monsterAt(cell.x, cell.y)
    );
    const hp = generation.roll(type.hp);
    const asleep = generation.rnd(100) < sleepChance;
    level.monsters.push({ ...cell, id, type, hp, maxHp: hp, asleep, energy: 0, wasVisible: false });
  }
  const itemCandidates = itemTypes.filter((type) => type.minDepth <= d && d <= type.maxDepth);
  const count = itemBase + itemStep * (d - 1);
  for (let i = 0; i < count; i++) {
    const type = generation.select(itemCandidates);
    let cell: RoomCell;
    do {
      cell = level.drawCell(generation);
    } while (level.at(cell.x, cell.y) !== '.' || level.itemAt(cell.x, cell.y));
    const item = makeItem(type, cell.x, cell.y);
    if (type.kind === 'gold') item.amount = generation.roll(type.dice);
    level.items.push(item);
  }
  level.placed = level.items.length;
  levels.push(level);
}
const pack = config[13].map((name) => {
  const type = itemTypes.find((type) => type.name === name);
  if (!type) throw new Error('Unknown starting item');
  return makeItem(type);
});
let weapon = pack.find((item) => item.type.kind === 'weapon');
let armor = pack.find((item) => item.type.kind === 'armor');
let depth = 1;
let px = levels[0].arrival.x;
let py = levels[0].arrival.y;
let hp = initialHp;
let maxHp = initialHp;
let playerLevel = 1;
let xp = 0;
let gold = 0;
let food = initialFood;
let poison = 0;
let turn = 1;
let succeeded = 0;
let failed = 0;
let unused = 0;
let moves = 0;
let picked = 0;
let quaffed = 0;
let read = 0;
let eaten = 0;
let wielded = 0;
let worn = 0;
let poisonDamage = 0;
let starvationDamage = 0;
let result: 'alive' | 'won' | 'died' = 'alive';
let cause = 'commands_exhausted';
let visible = new Set<number>();
const messages: string[] = [];
const maps: string[] = [];
const kills = new Map<string, number>();
interface AttackStats {
  count: number;
  hits: number;
  criticals: number;
  damage: number;
}
const playerAttacks: AttackStats = { count: 0, hits: 0, criticals: 0, damage: 0 };
const monsterAttacks: AttackStats = { count: 0, hits: 0, criticals: 0, damage: 0 };
const current = () => levels[depth - 1];
const log = (message: string) => {
  messages.push(`${String(turn).padStart(4, '0')} ${message}`);
};
const defense = () => 10 + (armor?.type.kind === 'armor' ? armor.type.armor + armor.bonus : 0);
const hunger = () =>
  food === 0 ? 'starving' : food <= weakAt ? 'weak' : food <= hungryAt ? 'hungry' : 'normal';
function die(reason: string): void {
  cause = reason;
  result = 'died';
  log('You die.');
}
function experience(amount: number): void {
  xp += amount;
  while (playerLevel <= thresholds.length && xp >= thresholds[playerLevel - 1]) {
    playerLevel++;
    const gain = game.roll(hitdie);
    maxHp += gain;
    hp += gain;
    log(`Welcome to level ${playerLevel}.`);
  }
}
function updateView(): void {
  const level = current();
  visible = fieldOfView(level, px, py, radius);
  for (const i of visible) {
    const item = level.itemAt(i % width, Math.floor(i / width));
    level.memory[i] = item ? symbol(item) : level.terrain[i];
  }
  for (const monster of level.monsters) {
    const seen = visible.has(level.index(monster.x, monster.y));
    if (seen && !monster.wasVisible) log(`You see the ${monster.type.name}.`);
    monster.wasVisible = seen;
  }
}
function countAttack(stats: AttackStats, outcome: Attack): void {
  stats.count++;
  if (outcome.hit) stats.hits++;
  if (outcome.critical) stats.criticals++;
  stats.damage += outcome.damage;
}
function playerAttack(monster: Monster): void {
  monster.asleep = false;
  let modifier = playerLevel;
  let bonus = 0;
  let dice = parseDice('1d2');
  if (weapon?.type.kind === 'weapon') {
    modifier += weapon.type.toHit + weapon.bonus;
    bonus = weapon.bonus;
    dice = weapon.type.damage;
  }
  if (hunger() === 'weak' || hunger() === 'starving') modifier -= 2;
  const outcome = attack(game, modifier, monster.type.defense, dice, bonus);
  countAttack(playerAttacks, outcome);
  if (!outcome.hit) {
    log(`You miss the ${monster.type.name}.`);
    return;
  }
  log(`You hit the ${monster.type.name}${outcome.critical ? ' hard' : ''} for ${outcome.damage}.`);
  monster.hp -= outcome.damage;
  if (monster.hp <= 0) {
    log(`You kill the ${monster.type.name}.`);
    const level = current();
    level.monsters.splice(level.monsters.indexOf(monster), 1);
    level.killed++;
    kills.set(monster.type.name, (kills.get(monster.type.name) ?? 0) + 1);
    experience(monster.type.xp);
  }
}
function monsterAttack(monster: Monster): void {
  const outcome = attack(game, monster.type.toHit, defense(), monster.type.damage, 0);
  countAttack(monsterAttacks, outcome);
  if (!outcome.hit) {
    log(`The ${monster.type.name} misses you.`);
    return;
  }
  log(`The ${monster.type.name} hits you${outcome.critical ? ' hard' : ''} for ${outcome.damage}.`);
  hp -= outcome.damage;
  if (hp <= 0) die(`killed_by ${monster.type.name}`);
  else if (monster.type.traits.includes('P')) {
    poison += 5;
    log('You are poisoned.');
  }
}
function execute(command: string[]): boolean {
  const [verb, argument] = command;
  const level = current();
  if (verb === 'wait') return true;
  if (verb === 'move') {
    const direction = directions.find((d) => d.name === argument);
    if (!direction) throw new Error('Unknown direction');
    const x = px + direction.x;
    const y = py + direction.y;
    if (!passable(level, x, y)) {
      log('You bump into a wall.');
      return false;
    }
    if (!canMove(level, px, py, direction.x, direction.y)) {
      log('You cannot move diagonally through a door.');
      return false;
    }
    const monster = level.monsterAt(x, y);
    if (monster) playerAttack(monster);
    else {
      px = x;
      py = y;
      moves++;
      const item = level.itemAt(x, y);
      if (item) log(`You see ${referenceName(item)} here.`);
      else if (level.at(x, y) === '>') log('There is a staircase down here.');
    }
    return true;
  }
  if (verb === 'descend') {
    if (level.at(px, py) !== '>') {
      log('There are no stairs here.');
      return false;
    }
    depth++;
    px = current().arrival.x;
    py = current().arrival.y;
    log(`You descend to depth ${depth}.`);
    return true;
  }
  if (verb === 'pickup') {
    const item = level.itemAt(px, py);
    if (!item) {
      log('There is nothing here.');
      return false;
    }
    if (item.type.kind === 'gold') {
      gold += item.amount;
      log(`You pick up ${displayName(item)}.`);
    } else if (item.type.kind === 'amulet') {
      log('You pick up the amulet.');
      log('You win!');
      result = 'won';
      cause = 'amulet';
    } else {
      if (pack.length === packLimit) {
        log('Your pack is full.');
        return false;
      }
      pack.push(item);
      log(`You pick up the ${displayName(item)} (${pack.length}).`);
    }
